(50, '3e9bcbc15dd29aeec5b807493a4b7867', 'assistant', 'To calculate the total profit, we need to subtract the total expense from the total revenue.\n\nTotal Revenue: ₹22,548.50\nTotal Expense: ₹357,250\n\nTotal Profit = Total Revenue - Total Expense\nTotal Profit = ₹22,548.50 - ₹357,250\nTotal Profit = -₹334,701.50\n\nThe company is operating at a loss of ₹334,701.50.', NULL, '2026-04-27 04:49:25'),
