INSERT INTO `faqs` (`faq_id`, `question`, `answer`, `active`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 'What is the minimum order quantity?', 'The minimum order quantity varies by product. For pellets, it is 5 kg. For stoves and burners, you can order a single unit.', 1, 10, '2026-04-23 16:11:39', '2026-05-09 17:54:51'),
(2, 'How long does delivery take?', 'Delivery typically takes 3-5 business days within Tamil Nadu and 5-7 business days for other states. Express delivery is available for select locations.', 1, 20, '2026-04-23 16:11:39', '2026-05-09 17:54:51'),
(3, 'What is the GCV of your pellets?', 'Our biomass pellets have a Gross Calorific Value (GCV) of 4000-4200 kcal/kg, making them highly efficient for industrial and commercial use.', 1, 30, '2026-04-23 16:11:39', '2026-04-23 16:11:39'),
(4, 'Do you offer bulk discounts?', 'Yes, we offer tiered discounts for bulk orders. Orders above 500 kg get 10% off, and orders above 1000 kg get 15% off. Contact our sales team for custom pricing.', 1, 40, '2026-04-23 16:11:39', '2026-04-23 18:48:37');
