DELIMITER $$
--
-- Procedures
--
CREATE DEFINER=`u952547820_demo`@`127.0.0.1` PROCEDURE `sp_generate_order_number` (OUT `new_order_number` VARCHAR(50))   BEGIN
    DECLARE order_count INT;
    DECLARE order_prefix VARCHAR(10);
    
    SELECT setting_value INTO order_prefix 
    FROM settings 
    WHERE setting_key = 'order_prefix';
    
    SELECT COUNT(*) INTO order_count FROM orders;
    
    SET new_order_number = CONCAT(
        order_prefix,
        '-',
        DATE_FORMAT(NOW(), '%Y%m%d'),
        LPAD(order_count + 1, 4, '0')
    );
END$$

CREATE DEFINER=`u952547820_demo`@`127.0.0.1` PROCEDURE `sp_get_active_orders_count` ()   BEGIN
    SELECT COUNT(*) AS active_orders_count
    FROM orders
    WHERE order_status IN ('pending', 'confirmed', 'processing', 'shipped');
END$$

CREATE DEFINER=`u952547820_demo`@`127.0.0.1` PROCEDURE `sp_get_order_details` (IN `p_order_id` INT)   BEGIN
    -- Order header
    SELECT 
        o.*,
        u.name AS customer_name,
        u.email,
        u.phone,
        u.user_type,
        u.company_name,
        u.gst_number
    FROM orders o
    JOIN users u ON o.user_id = u.user_id
    WHERE o.order_id = p_order_id;
    
    -- Order items
    SELECT 
        oi.*,
        p.product_name,
        p.product_type,
        p.description
    FROM order_items oi
    JOIN products p ON oi.product_id = p.product_id
    WHERE oi.order_id = p_order_id;
END$$

CREATE DEFINER=`u952547820_demo`@`127.0.0.1` PROCEDURE `sp_get_order_statistics` (IN `p_days` INT)   BEGIN
    SELECT 
        DATE(created_at) AS order_date,
        COUNT(*) AS total_orders,
        SUM(total_amount) AS total_revenue,
        AVG(total_amount) AS avg_order_value,
        COUNT(CASE WHEN order_status = 'delivered' THEN 1 END) AS delivered_orders,
        COUNT(CASE WHEN order_status = 'cancelled' THEN 1 END) AS cancelled_orders
    FROM orders
    WHERE created_at >= DATE_SUB(CURDATE(), INTERVAL p_days DAY)
    GROUP BY DATE(created_at)
    ORDER BY order_date DESC;
END$$

CREATE DEFINER=`u952547820_demo`@`127.0.0.1` PROCEDURE `sp_get_user_orders` (IN `p_user_id` INT)   BEGIN
    SELECT 
        o.order_id,
        o.order_number,
        o.total_amount,
        o.delivery_fee,
        o.order_status,
        o.payment_status,
        o.created_at,
        COUNT(oi.item_id) AS total_items,
        SUM(oi.quantity) AS total_quantity
    FROM orders o
    LEFT JOIN order_items oi ON o.order_id = oi.order_id
    WHERE o.user_id = p_user_id
    GROUP BY o.order_id
    ORDER BY o.created_at DESC;
END$$

DELIMITER ;

