DROP TABLE IF EXISTS `v_active_orders`;

CREATE ALGORITHM=UNDEFINED DEFINER=`u952547820_demo`@`127.0.0.1` SQL SECURITY DEFINER VIEW `v_active_orders`  AS SELECT `o`.`order_id` AS `order_id`, `o`.`order_number` AS `order_number`, `u`.`name` AS `customer_name`, `u`.`email` AS `email`, `u`.`phone` AS `phone`, `u`.`user_type` AS `user_type`, `o`.`total_amount` AS `total_amount`, `o`.`order_status` AS `order_status`, `o`.`payment_status` AS `payment_status`, `o`.`created_at` AS `created_at`, count(`oi`.`item_id`) AS `total_items` FROM ((`orders` `o` join `users` `u` on(`o`.`user_id` = `u`.`user_id`)) left join `order_items` `oi` on(`o`.`order_id` = `oi`.`order_id`)) WHERE `o`.`order_status` not in ('delivered','cancelled') GROUP BY `o`.`order_id`, `o`.`order_number`, `u`.`name`, `u`.`email`, `u`.`phone`, `u`.`user_type`, `o`.`total_amount`, `o`.`order_status`, `o`.`payment_status`, `o`.`created_at` ;

