--
-- Structure for view `v_order_statistics`
--
DROP TABLE IF EXISTS `v_order_statistics`;

CREATE ALGORITHM=UNDEFINED DEFINER=`u952547820_demo`@`127.0.0.1` SQL SECURITY DEFINER VIEW `v_order_statistics`  AS SELECT cast(`orders`.`created_at` as date) AS `order_date`, count(0) AS `total_orders`, sum(`orders`.`total_amount`) AS `total_revenue`, avg(`orders`.`total_amount`) AS `avg_order_value`, count(case when `orders`.`order_status` = 'delivered' then 1 end) AS `delivered_orders`, count(case when `orders`.`order_status` = 'cancelled' then 1 end) AS `cancelled_orders`, count(case when `orders`.`order_status` in ('pending','confirmed','processing','shipped') then 1 end) AS `active_orders` FROM `orders` GROUP BY cast(`orders`.`created_at` as date) ORDER BY cast(`orders`.`created_at` as date) DESC ;

